css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .92); position: relative; overflow: hidden; border-radius: 6%; background: #0b1220; }
.loader::after { content: ''; position: absolute; inset: 0; background: var(--accent-2); -webkit-mask-image: radial-gradient(circle, transparent 0 30%, #000 33%); mask-image: radial-gradient(circle, transparent 0 30%, #000 33%); -webkit-mask-size: 25% 25%; mask-size: 25% 25%; }
.loader span { position: absolute; width: calc(var(--loader-size) * .2); height: calc(var(--loader-size) * .2); border-radius: 50%; background: radial-gradient(circle at 36% 32%, color-mix(in srgb, #fff 42%, var(--accent)), var(--accent)); animation: disc-drop calc(var(--loader-speed) * 2.7) cubic-bezier(.5, 0, .7, 1) infinite; }
.loader span:nth-child(1) { left: 3%; }
.loader span:nth-child(2) { left: 28%; background: radial-gradient(circle at 36% 32%, #fff, color-mix(in srgb, #fff 46%, var(--accent))); animation-delay: calc(var(--loader-speed) * .9); }
.loader span:nth-child(3) { left: 53%; animation-delay: calc(var(--loader-speed) * 1.8); }
@keyframes disc-drop { 0% { opacity: 0; top: -24%; } 8% { opacity: 1; } 34% { top: 70%; } 42% { top: 60%; } 50% { top: 70%; } 88% { opacity: 1; top: 70%; } 100% { opacity: 0; top: 70%; } }
